INSERT INTO Leader_Flavors SELECT 'LEADER_VILTRUM_THRAGG',Type,CASE Type WHEN 'FLAVOR_OFFENSE' THEN 10 WHEN 'FLAVOR_DEFENSE' THEN 7 WHEN 'FLAVOR_CITY_DEFENSE' THEN 7 WHEN 'FLAVOR_EXPANSION' THEN 9 WHEN 'FLAVOR_MILITARY_TRAINING' THEN 10 WHEN 'FLAVOR_SCIENCE' THEN 7 WHEN 'FLAVOR_PRODUCTION' THEN 9 WHEN 'FLAVOR_GOLD' THEN 6 WHEN 'FLAVOR_CULTURE' THEN 3 WHEN 'FLAVOR_DIPLOMACY' THEN 2 WHEN 'FLAVOR_WONDER' THEN 2 WHEN 'FLAVOR_AIR' THEN 8 WHEN 'FLAVOR_NUKE' THEN 8 WHEN 'FLAVOR_NAVAL' THEN 5 ELSE 5 END FROM Flavors;
INSERT INTO Leader_MajorCivApproachBiases SELECT 'LEADER_VILTRUM_THRAGG',MajorCivApproachType,CASE WHEN MajorCivApproachType LIKE '%WAR' OR MajorCivApproachType LIKE '%CONQUEST' THEN 10 WHEN MajorCivApproachType LIKE '%FRIENDLY' THEN 2 ELSE 6 END FROM Leader_MajorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
INSERT INTO Leader_MinorCivApproachBiases SELECT 'LEADER_VILTRUM_THRAGG',MinorCivApproachType,CASE WHEN MinorCivApproachType LIKE '%WAR' OR MinorCivApproachType LIKE '%CONQUEST' THEN 10 WHEN MinorCivApproachType LIKE '%FRIENDLY' THEN 2 ELSE 6 END FROM Leader_MinorCivApproachBiases WHERE LeaderType='LEADER_WASHINGTON';
