-- All effects are scoped to newly declared Viltrum types.
UPDATE Building_YieldChanges SET Yield=Yield+2 WHERE BuildingType='BUILDING_VILTRUM_COMPLEX' AND YieldType='YIELD_PRODUCTION';
UPDATE Building_YieldChanges SET Yield=Yield+1 WHERE BuildingType='BUILDING_VILTRUM_COMPLEX' AND YieldType='YIELD_FOOD';
UPDATE Building_Flavors SET Flavor=40 WHERE BuildingType='BUILDING_VILTRUM_COMPLEX' AND FlavorType='FLAVOR_MILITARY_TRAINING';
UPDATE Unit_Flavors SET Flavor=8 WHERE UnitType='UNIT_VILTRUM_WARRIOR';
